def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start_row < rows and 0 <= start_col < cols and grid[start_row][start_col] == '.'):
        return []
    if not (0 <= goal_row < rows and 0 <= goal_col < cols and grid[goal_row][goal_col] == '.'):
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) != start

    def dfs(current, path, depth, max_depth):
        if depth > max_depth:
            return False
        r, c = current
        if (r, c) == goal:
            path.append((r, c))
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                path.append((nr, nc))
                if dfs((nr, nc), path, depth + 1, max_depth):
                    return True
                path.pop()
        return False

    # Iterative Deepening DFS
    max_depth = 0
    while True:
        path = [start]
        if dfs(start, path, 1, max_depth):
            return path
        max_depth += 1
        if max_depth > rows * cols:
            return []

