        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                neighbors.append((nx, ny))
        return neighbors

    def dfs(current, g, bound, path, visited, parent):
        f = g + manhattan(current)
        if f > bound:
            return f
        if current == goal:
            return g
        visited.add(current)
        min_f = float('inf')
        for neighbor in get_neighbors(current):
            if neighbor not in visited:
                parent[neighbor] = current
                result = dfs(neighbor, g + 1, bound, path, visited, parent)
                if result != float('inf'):
                    min_f = min(min_f, result)
                visited.remove(current)
                if result == float('inf'):
                    return float('inf')
        return min_f

